          "id": "WI-39615",
          "kind": "change",
          "title": "WS cutover P-001c: rehearsal, judge, and operational state — durable Postgres authority",
          "state": "done",
          "completedAt": "2026-08-17T06:16:51.860Z",
          "completionAuthority": "committed",
